$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'package.json')) {
    Write-Host 'ERROR: run from project root.' -ForegroundColor Red
    exit 1
}
$files = @{}
$files['app/(app)/system/page.tsx'] = ''
$files['app/(app)/system/actions.ts'] = ''
$files['app/(app)/system/_components/lock-control.tsx'] = ''
$files['components/app/sidebar.tsx'] = ''

Write-Host '-> Step 1: /system page UI only (no enforcement)' -ForegroundColor Cyan
foreach ($path in $files.Keys) {
    $content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($files[$path]))
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $fullPath = Join-Path -Path (Get-Location) -ChildPath $path
    [System.IO.File]::WriteAllText($fullPath, $content, [System.Text.UTF8Encoding]::new($false))
    Write-Host ('  + ' + $path) -ForegroundColor Green
}
Write-Host ''
Write-Host 'Done. Push to deploy. Then test:' -ForegroundColor Green
Write-Host '  1. Sign in as Coach Monson' -ForegroundColor Gray
Write-Host '  2. Sidebar should show new System entry' -ForegroundColor Gray
Write-Host '  3. Click System -> see lock control UI' -ForegroundColor Gray
Write-Host '  4. Sign in as test rep -> dashboard still works' -ForegroundColor Gray